90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OCTET_STRING: u8 = 0x04;
111	    const TAG_BOOLEAN: u8 = 0x01;
112	    const TAG_OID: u8 = 0x06;
113	    const TAG_SEQUENCE: u8 = 0x30;
114	    const TAG_SET: u8 = 0x31;
115	    const TAG_UTC_TIME: u8 = 0x17;
116	    const TAG_GENERALIZED_TIME: u8 = 0x18;
117	    const TAG_PRINTABLE_STRING: u8 = 0x13;
118	    const TAG_UNIVERSAL_STRING: u8 = 0x1C;
119	    const TAG_BMP_STRING: u8 = 0x1E;
120	
121	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
122	    /// length encodings and truncated data.
123	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
124	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
125	        if tag & 0x1F == 0x1F {
126	            return Err("multi-byte tags are not supported".to_string());
127	        }
128	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
129	        let (len, header_len) = match first_len {
130	            0x00..=0x7F => (first_len as usize, 2),
131	            0x80 => return Err("indefinite length is not valid DER".to_string()),
132	            0xFF => return Err("reserved length byte".to_string()),
133	            long => {
134	                let n = (long & 0x7F) as usize;
135	                if !(1..=4).contains(&n) {
136	                    return Err("length is too large".to_string());
137	                }
138	                let bytes = buf
139	                    .get(2..2 + n)
140	                    .ok_or_else(|| "truncated long length".to_string())?;
141	                if bytes[0] == 0 {
142	                    return Err("non-minimal length encoding".to_string());
143	                }
144	                let mut len = 0usize;
145	                for &b in bytes {
146	                    len = len
147	                        .checked_shl(8)
148	                        .and_then(|l| l.checked_add(b as usize))
149	                        .ok_or_else(|| "length overflow".to_string())?;
150	                }
151	                if len < 0x80 {
152	                    return Err("non-minimal length encoding".to_string());
153	                }
154	                (len, 2 + n)
155	            }
156	        };
157	        let total = header_len
158	            .checked_add(len)
159	            .filter(|&t| t <= buf.len())
160	            .ok_or_else(|| "truncated TLV content".to_string())?;
161	        Ok((
162	            Tlv {
163	                tag,
164	                content: &buf[header_len..total],
165	            },
166	            &buf[total..],
167	        ))
168	    }
169	
170	    fn read_tagged<'a>(
171	        buf: &'a [u8],
172	        tag: u8,
173	        what: &str,
174	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
175	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
176	        if tlv.tag != tag {
177	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
178	        }
179	        Ok((tlv, rest))
180	    }
181	
182	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
183	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
184	        // signatureValue BIT STRING } — and nothing trailing.
185	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
186	        if !rest.is_empty() {
187	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
188	        }
189	
190	        let c = cert.content;
191	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
192	        let (outer_alg, c) = read_tagged(c, TAG_SEQUENCE, "outer signatureAlgorithm")?;
193	        let outer_alg = parse_signature_algorithm(outer_alg, "outer signatureAlgorithm")?;
194	        let (sig_value, c) = read_tlv(c)?;
195	        if sig_value.tag != TAG_BIT_STRING {
196	            return Err("signature must be a BIT STRING".to_string());
197	        }
198	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
199	            return Err("invalid signature BIT STRING".to_string());
200	        }
201	        if !c.is_empty() {
202	            return Err("trailing data in Certificate".to_string());
203	        }
204	
205	        // TBSCertificate ::= SEQUENCE {
206	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
207	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
208	        let t = tbs.content;
209	        let (first, t2) = read_tlv(t)?;
210	        let (version, t) = if first.tag == 0xA0 {
211	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
212	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
213	                return Err("invalid certificate version".to_string());
214	            }
215	            (ver.content[0], t2)
216	        } else {
217	            // No explicit version: v1 certificate.
218	            (0u8, t)
219	        };
220	
221	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
222	        let t = t3;
223	        let (tbs_alg, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
224	        let tbs_alg = parse_signature_algorithm(tbs_alg, "tbs signatureAlgorithm")?;
225	        if tbs_alg != outer_alg {
226	            return Err(mismatch_message(&outer_alg, &tbs_alg));
227	        }
228	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
229	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
230	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
231	        let (spki, t_after_spki) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
232	        check_spki(spki)?;
233	        // Optional tail of TBSCertificate, in a fixed order:
234	        //   issuerUniqueID  [1] IMPLICIT BIT STRING  (v2/v3, at most once)
235	        //   subjectUniqueID [2] IMPLICIT BIT STRING  (v2/v3, at most once)
236	        //   extensions      [3] EXPLICIT             (v3 only, at most once,
237	        //                                             and the last field)
238	        // Nothing else may follow subjectPublicKeyInfo: fields cannot be
239	        // skipped, reordered or dropped. The extensions interior is decoded in
240	        // full by `check_extensions`; the unique IDs carry BIT STRING content
241	        // directly (implicit tagging), validated by `check_bit_string`.
242	        let mut t = t_after_spki;
243	        let mut issuer_uid_seen = false;
244	        let mut subject_uid_seen = false;
245	        let mut extensions_present = false;
246	        while !t.is_empty() {
247	            let tag_hint = t.first().copied();
248	            let (field, rest) = read_tlv(t).map_err(|e| match tag_hint {
249	                Some(0x81) => format!("issuerUniqueID: {e}"),
250	                Some(0x82) => format!("subjectUniqueID: {e}"),
251	                // A truncated field whose tag is already readable can still
252	                // be located: tag 0xA3 is the extensions field.
253	                Some(0xA3) => format!("extensions field: {e}"),
254	                _ => e,
255	            })?;
256	            match field.tag {
257	                0x81 | 0x82 => {
258	                    let what = if field.tag == 0x81 {
259	                        "issuerUniqueID"
260	                    } else {
261	                        "subjectUniqueID"
262	                    };
263	                    if version < 1 {
264	                        return Err(format!(
265	                            "{what} is only allowed in v2 or v3 certificates, this is v1"
266	                        ));
267	                    }
268	                    if extensions_present {
269	                        return Err(format!(
270	                            "{what} must appear before the extensions field, \
271	                             which is the last field of tbsCertificate"
272	                        ));
273	                    }
274	                    if field.tag == 0x81 {
275	                        if issuer_uid_seen {
276	                            return Err("duplicate issuerUniqueID field".to_string());
277	                        }
278	                        if subject_uid_seen {
279	                            return Err(
280	                                "issuerUniqueID must appear before subjectUniqueID".to_string()
281	                            );
282	                        }
283	                        issuer_uid_seen = true;
284	                    } else if subject_uid_seen {
285	                        return Err("duplicate subjectUniqueID field".to_string());
286	                    } else {
287	                        subject_uid_seen = true;
288	                    }
289	                    check_bit_string(field.content, what)?;
290	                }
291	                0xA1 | 0xA2 => {
292	                    let what = if field.tag == 0xA1 {
293	                        "issuerUniqueID"
294	                    } else {
295	                        "subjectUniqueID"
296	                    };
297	                    return Err(format!(
298	                        "{what} must be an implicitly tagged primitive BIT STRING \
299	                         (tag 0x{:02X}); constructed tag 0x{:02X} is an explicit wrapper \
300	                         and is not allowed",
301	                        field.tag - 0x20,
302	                        field.tag
303	                    ));
304	                }
305	                0xA3 => {
306	                    if extensions_present {
307	                        return Err("duplicate extensions field".to_string());
308	                    }
309	                    if version != 2 {
310	                        let name = if version == 0 {
311	                            "v1"
312	                        } else {
313	                            "v2"
314	                        };
315	                        return Err(format!(
316	                            "extensions are only allowed in v3 certificates, this is {name}"
317	                        ));
318	                    }
319	                    check_extensions(field.content)?;
320	                    extensions_present = true;
321	                }
322	                other => {
323	                    return Err(format!(
324	                        "unexpected field after subjectPublicKeyInfo (tag 0x{other:02X}): \
325	                         only issuerUniqueID [1], subjectUniqueID [2] and extensions [3] \
326	                         are allowed there, and extensions must be last"
327	                    ));
328	                }
329	            }
330	            t = rest;
331	        }
332	
333	        let serial_hex = format_serial(serial.content)?;
334	        let issuer = format_name(issuer, "issuer")?;
335	        let subject = format_name(subject, "subject")?;
336	
337	        let v = validity.content;
338	        let (nb, v2) = read_tlv(v)?;
339	        let (na, v3) = read_tlv(v2)?;
340	        if !v3.is_empty() {
341	            return Err("trailing data in validity".to_string());
342	        }
343	        let not_before = format_time(nb)?;
344	        let not_after = format_time(na)?;
345	
346	        Ok(Cert {
347	            subject,
348	            issuer,
349	            serial_hex,
350	            not_before,
351	            not_after,
352	        })
353	    }
354	
355	    /// Validate the content of the extensions field, i.e. the bytes wrapped
356	    /// by `[3] EXPLICIT`:
357	    ///
358	    /// ```text
359	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
360	    /// Extension  ::= SEQUENCE {
361	    ///   extnID    OBJECT IDENTIFIER,
362	    ///   critical  BOOLEAN DEFAULT FALSE,
363	    ///   extnValue OCTET STRING }
364	    /// ```
365	    ///
366	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
367	    /// Every extension must contain its OID and OCTET STRING in that order,
368	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
369	    /// Extension contents are never interpreted: unknown but well-formed
370	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
371	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
372	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
373	        if !rest.is_empty() {
374	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
375	        }
376	        if list.content.is_empty() {
377	            return Err("extensions SEQUENCE is empty".to_string());
378	        }
379	
380	        let mut buf = list.content;
381	        while !buf.is_empty() {
382	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
383	            buf = rest;
384	
385	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
386	            parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
387	
388	            // critical is optional; whatever stands between the OID and the
389	            // OCTET STRING must be exactly one BOOLEAN if it is present.
390	            let (maybe_bool, after_critical) = read_tlv(after_oid)
391	                .map_err(|e| format!("extension after OID: {e}"))?;
392	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
393	                match maybe_bool.content {
394	                    [0xFF] => {}
395	                    [0x00] => {
396	                        return Err(
397	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
398	                                .to_string()
399	                        )
400	                    }
401	                    _ => {
402	                        return Err(
403	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
404	                        )
405	                    }
406	                }
407	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
408	            } else {
409	                // Not a BOOLEAN: this element must itself be the extnValue.
410	                if maybe_bool.tag != TAG_OCTET_STRING {
411	                    return Err(format!(
412	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
413	                         got tag 0x{:02X}",
414	                        maybe_bool.tag
415	                    ));
416	                }
417	                (maybe_bool, after_critical)
418	            };
419	            // An empty OCTET STRING is legal; its bytes are not interpreted.
420	            let _ = octets.content;
421	            if !after_octets.is_empty() {
422	                return Err("trailing data in extension".to_string());
423	            }
424	        }
425	        Ok(())
426	    }
427	
428	    /// SubjectPublicKeyInfo ::= SEQUENCE {
429	    ///   algorithm        AlgorithmIdentifier,
430	    ///   subjectPublicKey BIT STRING }
431	    /// Nothing may be missing and no extra elements may follow.
432	    fn check_spki(spki: Tlv) -> Result<(), String> {
433	        let (alg, rest) = read_tagged(
434	            spki.content,
435	            TAG_SEQUENCE,
436	            "subjectPublicKeyInfo algorithm identifier",
437	        )?;
438	        check_algorithm_identifier(alg)?;
439	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
440	        check_bit_string(key.content, "subjectPublicKey")?;
441	        if !rest.is_empty() {
442	            return Err("trailing data in subjectPublicKeyInfo".to_string());
443	        }
444	        Ok(())
445	    }
446	
447	    /// Why the content of an AlgorithmIdentifier SEQUENCE failed the shared
448	    /// structural check in `split_algorithm_identifier`. Each variant carries
449	    /// only the raw facts; every reader maps them onto its own established
450	    /// error wording (the public-key position names "algorithm OID" and
451	    /// "algorithm parameters", the signature algorithm positions name their
452	    /// own location).
453	    enum AlgIdError {
454	        /// The leading OID element could not be read as one complete TLV.
455	        OidRead(String),
456	        /// The first element is present but is not an OID.
457	        OidTag(u8),
458	        /// The OID element exists but its content is not a valid OID
459	        /// (empty, truncated or non-minimal base-128 arcs).
460	        OidContent(String),
461	        /// A parameter element follows the OID but cannot be read as one
462	        /// complete TLV.
463	        ParamsRead(String),
464	        /// Bytes remain after the parameter element: parameters are one
465	        /// OPTIONAL element, never several.
466	        ExtraAfterParams,
467	    }
468	
469	    /// Split the content of an AlgorithmIdentifier SEQUENCE into its
470	    /// algorithm OID and optional parameters, enforcing the structure every
471	    /// reader of an algorithm identifier shares:
472	    ///
473	    /// ```text
474	    /// AlgorithmIdentifier ::= SEQUENCE {
475	    ///   algorithm  OBJECT IDENTIFIER,
476	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
477	    /// ```
478	    ///
479	    /// The content must start with one complete, shortest-encoded OID,
480	    /// followed by either nothing or exactly one complete DER parameter
481	    /// value, and nothing after that. Absent parameters and an explicit NULL
482	    /// are both accepted and the parameter content is never interpreted for
483	    /// any particular algorithm; an unknown but well-formed OID is accepted.
484	    /// The parameter TLV is returned as its full original encoding (tag,
485	    /// length and content), sliced straight from the input, so callers that
486	    /// compare two identifiers can do so at the DER byte level.
487	    fn split_algorithm_identifier(
488	        content: &[u8],
489	    ) -> Result<(Tlv<'_>, Option<&[u8]>), AlgIdError> {
490	        let (oid, rest) = read_tlv(content).map_err(AlgIdError::OidRead)?;
491	        if oid.tag != TAG_OID {
492	            return Err(AlgIdError::OidTag(oid.tag));
493	        }
494	        parse_oid(oid.content).map_err(AlgIdError::OidContent)?;
495	        let params = if rest.is_empty() {
496	            None
497	        } else {
498	            let (_params, after) = read_tlv(rest).map_err(AlgIdError::ParamsRead)?;
499	            if !after.is_empty() {
500	                return Err(AlgIdError::ExtraAfterParams);
501	            }
502	            // Keep the full parameter TLV (tag, length and content), sliced
503	            // straight from the enclosing content; `read_tlv` already proved
504	            // it is a complete value.
505	            Some(&rest[..rest.len() - after.len()])
506	        };
507	        Ok((oid, params))
508	    }
509	
510	    /// Validate the AlgorithmIdentifier inside SubjectPublicKeyInfo: the
511	    /// shared structure from `split_algorithm_identifier`, reported with the
512	    /// public-key position's own wording.
513	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
514	        split_algorithm_identifier(alg.content)
515	            .map(|_| ())
516	            .map_err(|e| match e {
517	                AlgIdError::OidRead(e) => format!("algorithm OID: {e}"),
518	                AlgIdError::OidTag(tag) => {
519	                    format!("expected algorithm OID (tag 0x06), got 0x{tag:02X}")
520	                }
521	                AlgIdError::OidContent(e) => format!("algorithm OID: {e}"),
522	                AlgIdError::ParamsRead(e) => format!("algorithm parameters: {e}"),
523	                AlgIdError::ExtraAfterParams => "multiple algorithm parameters".to_string(),
524	            })
525	    }
526	
527	    /// One of the certificate's two signature algorithm descriptions, kept as
528	    /// raw slices so two copies can be compared at the DER byte level: the OID
529	    /// content (arcs in their shortest encoding) and the complete parameter
530	    /// TLV (tag, length and content), or no parameter at all. An absent
531	    /// parameter and an explicit NULL are different representations.
532	    #[derive(Clone, Copy, PartialEq, Eq)]
533	    struct SignatureAlgorithm<'a> {
534	        oid_content: &'a [u8],
535	        params: Option<&'a [u8]>,
536	    }
537	
538	    /// Parse and fully validate one signatureAlgorithm SEQUENCE, applying the
539	    /// shared AlgorithmIdentifier structure from `split_algorithm_identifier`
540	    /// and keeping the raw pieces for the byte-level comparison of the two
541	    /// copies. `loc` names which of the two copies is being checked ("outer
542	    /// signatureAlgorithm" or the copy inside tbsCertificate) and prefixes
543	    /// every error message.
544	    fn parse_signature_algorithm<'a>(
545	        alg: Tlv<'a>,
546	        loc: &str,
547	    ) -> Result<SignatureAlgorithm<'a>, String> {
548	        let (oid, params) = split_algorithm_identifier(alg.content).map_err(|e| match e {
549	            AlgIdError::OidRead(e) => format!("{loc}: {e}"),
550	            AlgIdError::OidTag(tag) => format!(
551	                "{loc}: algorithm must start with an OID (tag 0x06), got tag 0x{tag:02X}"
552	            ),
553	            AlgIdError::OidContent(e) => format!("{loc}: {e}"),
554	            AlgIdError::ParamsRead(e) => format!("{loc}: algorithm parameters: {e}"),
555	            AlgIdError::ExtraAfterParams => {
556	                format!("{loc}: extra element after the algorithm parameters")
557	            }
558	        })?;
559	        Ok(SignatureAlgorithm {
560	            oid_content: oid.content,
561	            params,
562	        })
563	    }
564	
565	    /// Describe the disagreement between the outer signatureAlgorithm and the
566	    /// copy inside tbsCertificate. Both copies parse on their own; they merely
567	    /// fail to name the same algorithm or the same parameter representation.
568	    fn mismatch_message(outer: &SignatureAlgorithm<'_>, inner: &SignatureAlgorithm<'_>) -> String {
569	        const OUTER: &str = "the outer signatureAlgorithm";
570	        const INNER: &str = "the signatureAlgorithm in tbsCertificate";
571	        if outer.oid_content != inner.oid_content {
572	            let outer_oid = parse_oid(outer.oid_content)
573	                .map(|arcs| arcs_to_string(&arcs))
574	                .unwrap_or_else(|_| "?".to_string());
575	            let inner_oid = parse_oid(inner.oid_content)
576	                .map(|arcs| arcs_to_string(&arcs))
577	                .unwrap_or_else(|_| "?".to_string());
578	            return format!(
579	                "signature algorithm mismatch: {OUTER} names OID {outer_oid}, but {INNER} \
580	                 names OID {inner_oid}"
581	            );
582	        }
583	        match (outer.params, inner.params) {
584	            (Some(outer_params), Some(inner_params)) if outer_params != inner_params => {
585	                format!(
586	                    "signature algorithm mismatch: both copies name the same algorithm OID but \
587	                     their parameters have different DER encodings ({OUTER} has {}, {INNER} has {})",
588	                    hex_of(outer_params),
589	                    hex_of(inner_params),
590	                )
591	            }
592	            (Some(_), None) => format!(
593	                "signature algorithm mismatch: {OUTER} carries parameters but {INNER} omits them \
594	                 (an absent parameter and an explicit value are different representations)"
595	            ),
596	            (None, Some(_)) => format!(
597	                "signature algorithm mismatch: {INNER} carries parameters but {OUTER} omits them \
598	                 (an absent parameter and an explicit value are different representations)"
599	            ),
600	            // PartialEq already proved the copies unequal; reaching any other
601	            // arm here would be a logic error rather than a malformed cert.
602	            _ => "signature algorithm mismatch between the two signatureAlgorithm copies"
603	                .to_string(),
604	        }
605	    }
