607	    fn hex_of(bytes: &[u8]) -> String {
608	        let mut s = String::with_capacity(bytes.len() * 2);
609	        for b in bytes {
610	            write!(s, "{b:02X}").unwrap();
611	        }
612	        s
613	    }
