615	    /// Validate the DER content of a BIT STRING: one leading byte counting
616	    /// unused bits (0..=7), and when the count is nonzero those low bits of
617	    /// the final data byte must all be zero. An empty bit string is only
618	    /// legal with a zero count.
619	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
620	        let unused = *content
621	            .first()
622	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
623	        if unused > 7 {
624	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
625	        }
626	        let data = &content[1..];
627	        if data.is_empty() {
628	            if unused != 0 {
629	                return Err(format!(
630	                    "{what} BIT STRING declares {unused} unused bits but has no data"
631	                ));
632	            }
633	            return Ok(());
634	        }
635	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
636	            return Err(format!(
637	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
638	            ));
639	        }
640	        Ok(())
641	    }
