643	    /// Render the serial number as upper-case hex, matching the integer value
644	    /// (a DER sign-padding 0x00 byte is not part of the number).
645	    fn format_serial(content: &[u8]) -> Result<String, String> {
646	        if content.is_empty() {
647	            return Err("empty serial number".to_string());
648	        }
649	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
650	            return Err("non-minimal serial number encoding".to_string());
651	        }
652	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
653	            return Err("non-minimal serial number encoding".to_string());
654	        }
655	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
656	            return Err("negative serial number".to_string());
657	        }
658	        let digits = if content.len() > 1 && content[0] == 0x00 {
659	            &content[1..]
660	        } else {
661	            content
662	        };
663	        let mut s = String::with_capacity(digits.len() * 2);
664	        for b in digits {
665	            write!(s, "{b:02X}").unwrap();
666	        }
667	        if s.is_empty() {
668	            s.push_str("00");
669	        }
670	        Ok(s)
671	    }
