673	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
674	    /// multi-valued RDNs joined with '+'). Values of known attribute types
675	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
676	    /// when their tag has a text decoder; a known type carrying any other
677	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
678	    /// name and uses the '#' form carrying the value's full DER encoding in
679	    /// hex. Attributes without a known short name use their dotted OID with
680	    /// the same '#' form.
681	    ///
682	    /// Each RDN is a DER SET OF, so its complete AttributeTypeAndValue
683	    /// encodings must be sorted by their full encoding bytes (tag, then
684	    /// length, then content — the encoding, never the display name, dotted
685	    /// OID text or decoded value). The check is per RDN; it never reorders
686	    /// the members itself. `what` names the name being checked ("subject" or
687	    /// "issuer") so an ordering failure identifies it in the error message.
688	    fn format_name(name: Tlv, what: &str) -> Result<String, String> {
689	        let mut rdn_buf = name.content;
690	        let mut rdns: Vec<String> = Vec::new();
691	        while !rdn_buf.is_empty() {
692	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
693	            rdn_buf = rest;
694	
695	            let mut atv_buf = set.content;
696	            let mut parts = Vec::new();
697	            // Raw full encoding (tag, length and content) of each member of
698	            // this SET OF, straight from the certificate: DER SET OF ordering
699	            // compares the complete member encodings byte for byte. Equal
700	            // encodings may legitimately repeat and stay adjacent.
701	            let mut members: Vec<&[u8]> = Vec::new();
702	            while !atv_buf.is_empty() {
703	                let atv_start = atv_buf;
704	                let (atv, rest) =
705	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
706	                atv_buf = rest;
707	                members.push(&atv_start[..atv_start.len() - atv_buf.len()]);
708	
709	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
710	                let (value, after_value) = read_tlv(after_oid)?;
711	                if !after_value.is_empty() {
712	                    return Err("trailing data in attribute value".to_string());
713	                }
714	
715	                let oid_arcs = parse_oid(oid.content)?;
716	
717	                // The value's own type rules apply before any display decision:
718	                // a PrintableString must hold only the RFC 5280 PrintableString
719	                // alphabet, a BMPString must hold whole 16-bit BMP characters
720	                // and a UniversalString must hold whole 32-bit Unicode code
721	                // points, whether the attribute later renders as text for a
722	                // known short name or as '#'-hex for an unknown type. The hex
723	                // form must never let an illegal byte or code point through,
724	                // and illegal content cannot be dropped or replaced. An empty
725	                // value stays legal. `what` names the offending name
726	                // ("subject"/"issuer").
727	                if value.tag == TAG_PRINTABLE_STRING
728	                    && !is_printable_string(value.content)
729	                {
730	                    return Err(format!(
731	                        "{what} name: PrintableString attribute value contains an illegal \
732	                         character (only A-Z, a-z, 0-9, space and ' ( ) + , - . / : = ? are \
733	                         allowed)"
734	                    ));
735	                }
736	                if value.tag == TAG_BMP_STRING {
737	                    check_bmp_string(value.content, what)?;
738	                }
739	                if value.tag == TAG_UNIVERSAL_STRING {
740	                    check_universal_string(value.content, what)?;
741	                }
742	
743	                match oid_short_name(&oid_arcs) {
744	                    Some(label) => {
745	                        if is_text_value_tag(value.tag) {
746	                            // Supported string type: decode to escaped text.
747	                            // A decode failure (e.g. invalid UTF-8) means the
748	                            // certificate is corrupt; it must not be salvaged
749	                            // by falling back to the hex form.
750	                            let text = decode_attribute_value(value.tag, value.content)?;
751	                            parts.push(format!("{label}={}", escape_value(&text)));
752	                        } else {
753	                            // Known type but a legal value with no text decoder
754	                            // (SEQUENCE, OCTET STRING, ...): keep the short name
755	                            // and show the full original DER encoding as '#'-hex.
756	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)));
757	                        }
758	                    }
759	                    None => {
760	                        // Unknown attribute type: RFC 4514 requires the form
761	                        // OID=#hex, where the hex is the full DER encoding
762	                        // (tag, length and content) of the attribute value.
763	                        // Showing the value as hex does not bypass its type
764	                        // rules: UTF8String content must be valid UTF-8, a
765	                        // PrintableString must keep to its alphabet, a
766	                        // BMPString must hold legal BMP characters and a
767	                        // UniversalString must hold legal Unicode code points,
768	                        // checks already performed above before this match.
769	                        if value.tag == 0x0C {
770	                            std::str::from_utf8(value.content)
771	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
772	                        }
773	                        let hex = value_hex(after_oid, after_value);
774	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
775	                    }
776	                }
777	            }
778	            if parts.is_empty() {
779	                return Err("empty RelativeDistinguishedName".to_string());
780	            }
781	            check_rdn_der_order(&members, what)?;
782	            rdns.push(parts.join("+"));
783	        }
784	        rdns.reverse();
785	        Ok(rdns.join(","))
786	    }
