822	    /// Tags whose attribute values have a direct text decoding in
823	    /// `decode_attribute_value`. Every other tag that `read_tlv` accepts is a
824	    /// legal non-text value for display purposes and is rendered as '#'-hex.
825	    fn is_text_value_tag(tag: u8) -> bool {
826	        matches!(
827	            tag,
828	            0x0C | 0x12 | 0x13 | 0x14 | 0x16 | 0x1A | 0x1B | 0x1C | 0x1E
829	        )
830	    }
