832	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
833	        if content.is_empty() {
834	            return Err("empty OID".to_string());
835	        }
836	        let mut arcs = Vec::new();
837	        // The first subidentifier encodes the first two arcs as
838	        // 40*first + second and is itself a base-128 quantity, so it can
839	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
840	        let mut i = 0;
841	        let first = read_oid_arc(content, &mut i)?;
842	        match first {
843	            0..=39 => {
844	                arcs.push(0);
845	                arcs.push(first);
846	            }
847	            40..=79 => {
848	                arcs.push(1);
849	                arcs.push(first - 40);
850	            }
851	            _ => {
852	                arcs.push(2);
853	                arcs.push(first - 80);
854	            }
855	        }
856	        while i < content.len() {
857	            arcs.push(read_oid_arc(content, &mut i)?);
858	        }
859	        Ok(arcs)
860	    }
861	
862	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
863	    /// continuation bytes and non-minimal encodings.
864	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
865	        let start = *i;
866	        let mut value = 0u64;
867	        loop {
868	            let b = *content
869	                .get(*i)
870	                .ok_or_else(|| "truncated OID arc".to_string())?;
871	            value = value
872	                .checked_mul(128)
873	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
874	                .ok_or_else(|| "OID arc overflow".to_string())?;
875	            *i += 1;
876	            if b & 0x80 == 0 {
877	                break;
878	            }
879	        }
880	        if *i - start > 1 && content[start] == 0x80 {
881	            return Err("non-minimal OID arc encoding".to_string());
882	        }
883	        Ok(value)
884	    }
885	
886	    fn arcs_to_string(arcs: &[u64]) -> String {
887	        arcs.iter()
888	            .map(u64::to_string)
889	            .collect::<Vec<_>>()
890	            .join(".")
891	    }
