893	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
894	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
895	        let name = match arcs {
896	            [2, 5, 4, 3] => "CN",
897	            [2, 5, 4, 4] => "SN",
898	            [2, 5, 4, 5] => "serialNumber",
899	            [2, 5, 4, 6] => "C",
900	            [2, 5, 4, 7] => "L",
901	            [2, 5, 4, 8] => "ST",
902	            [2, 5, 4, 9] => "STREET",
903	            [2, 5, 4, 10] => "O",
904	            [2, 5, 4, 11] => "OU",
905	            [2, 5, 4, 12] => "title",
906	            [2, 5, 4, 17] => "postalAddress",
907	            [2, 5, 4, 18] => "postalCode",
908	            [2, 5, 4, 20] => "telephoneNumber",
909	            [2, 5, 4, 42] => "givenName",
910	            [2, 5, 4, 43] => "initials",
911	            [2, 5, 4, 44] => "generationQualifier",
912	            [2, 5, 4, 46] => "dnQualifier",
913	            [2, 5, 4, 65] => "pseudonym",
914	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
915	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
916	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
917	            _ => return None,
918	        };
919	        Some(name)
920	    }
