922	    /// Whether every byte belongs to the RFC 5280 PrintableString alphabet:
923	    /// A-Z, a-z, 0-9, space, and ' ( ) + , - . / : = ?. Every other byte
924	    /// (including @, _, tabs, newlines, NUL and 0x80..=0xFF) is illegal.
925	    /// An empty value passes, preserving the existing acceptance of empty
926	    /// contents.
927	    fn is_printable_string(content: &[u8]) -> bool {
928	        content.iter().all(|&b| matches!(
929	            b,
930	            b'A'..=b'Z'
931	                | b'a'..=b'z'
932	                | b'0'..=b'9'
933	                | b' '
934	                | b'\''
935	                | b'('
936	                | b')'
937	                | b'+'
938	                | b','
939	                | b'-'
940	                | b'.'
941	                | b'/'
942	                | b':'
943	                | b'='
944	                | b'?'
945	        ))
946	    }
947	
948	    /// Validate BMPString content: an even number of bytes read as big-endian
949	    /// 16-bit characters, each of which must be a Basic Multilingual Plane
950	    /// code point (U+0000..=U+FFFF) and never a UTF-16 surrogate
951	    /// (U+D800..=U+DFFF). Surrogates are not characters, so a lone high or
952	    /// low surrogate is corrupt, and so is an adjacent pair that UTF-16
953	    /// rules would combine into an astral-plane character — the pair must
954	    /// not be merged and displayed. An illegal value fails the whole
955	    /// certificate; bytes are never dropped or replaced to salvage it.
956	    /// Empty content stays legal, preserving the existing acceptance of
957	    /// empty values. `what` names the name being checked ("subject" or
958	    /// "issuer") so the error identifies the offending name.
959	    fn check_bmp_string(content: &[u8], what: &str) -> Result<(), String> {
960	        if content.len() % 2 != 0 {
961	            return Err(format!(
962	                "{what} name: BMPString attribute value has an odd length of {} byte(s) \
963	                 (the content must be a sequence of 16-bit characters)",
964	                content.len()
965	            ));
966	        }
967	        for pair in content.chunks_exact(2) {
968	            let unit = u16::from_be_bytes([pair[0], pair[1]]);
969	            if (0xD800..=0xDFFF).contains(&unit) {
970	                return Err(format!(
971	                    "{what} name: BMPString attribute value contains the surrogate code \
972	                     point U+{unit:04X}, which is not a legal character (U+D800..=U+DFFF \
973	                     are not characters and cannot appear, alone or in pairs)"
974	                ));
975	            }
976	        }
977	        Ok(())
978	    }
979	
980	    /// Validate UniversalString content: the bytes must form whole big-endian
981	    /// 32-bit Unicode code points, so the length must be a multiple of four,
982	    /// and every code point must lie in U+0000..=U+10FFFF and never be a
983	    /// UTF-16 surrogate (U+D800..=U+DFFF). A trailing incomplete unit, a lone
984	    /// surrogate (or a pair that UTF-16 rules would combine), or a value
985	    /// above the Unicode ceiling is corrupt; the whole certificate fails and
986	    /// no unit is dropped, replaced or merely hex-displayed to salvage it.
987	    /// Empty content stays legal, preserving the existing acceptance of empty
988	    /// values. `what` names the name being checked ("subject" or "issuer")
989	    /// so the error identifies the offending name.
990	    fn check_universal_string(content: &[u8], what: &str) -> Result<(), String> {
991	        if content.len() % 4 != 0 {
992	            return Err(format!(
993	                "{what} name: UniversalString attribute value has a length of {} byte(s), \
994	                 which is not a multiple of four (the content must be a sequence of \
995	                 big-endian 32-bit Unicode code points)",
996	                content.len()
997	            ));
998	        }
999	        for unit in content.chunks_exact(4) {
1000	            let cp = u32::from_be_bytes([unit[0], unit[1], unit[2], unit[3]]);
1001	            if (0xD800..=0xDFFF).contains(&cp) {
1002	                return Err(format!(
1003	                    "{what} name: UniversalString attribute value contains the surrogate code \
1004	                     point U+{cp:04X}, which is not a legal character (U+D800..=U+DFFF are \
1005	                     not characters and cannot appear, alone or in pairs)"
1006	                ));
1007	            }
1008	            if cp > 0x10FFFF {
1009	                return Err(format!(
1010	                    "{what} name: UniversalString attribute value contains the code point \
1011	                     U+{cp:04X}, which is above the Unicode maximum U+10FFFF"
1012	                ));
1013	            }
1014	        }
1015	        Ok(())
1016	    }
