1018	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
1019	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
1020	        let s = match tag {
1021	            0x0C => std::str::from_utf8(content)
1022	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
1023	                .to_string(),
1024	            // ASCII-family strings: every byte is also its Unicode code point.
1025	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
1026	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
1027	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
1028	            0x1E => {
1029	                if content.len() % 2 != 0 {
1030	                    return Err("odd-length BMPString".to_string());
1031	                }
1032	                // A BMPString character is one big-endian 16-bit BMP code
1033	                // point, never a UTF-16 surrogate: surrogate pairs must not
1034	                // be merged into astral-plane characters.
1035	                let mut s = String::with_capacity(content.len() / 2);
1036	                for c in content.chunks_exact(2) {
1037	                    let unit = u16::from_be_bytes([c[0], c[1]]);
1038	                    let ch = char::from_u32(unit as u32)
1039	                        .ok_or_else(|| "surrogate code point in BMPString".to_string())?;
1040	                    s.push(ch);
1041	                }
1042	                s
1043	            }
1044	            0x1C => {
1045	                if content.len() % 4 != 0 {
1046	                    return Err("invalid UniversalString length".to_string());
1047	                }
1048	                let mut s = String::new();
1049	                for c in content.chunks_exact(4) {
1050	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
1051	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
1052	                        return Err("invalid code point in UniversalString".to_string());
1053	                    }
1054	                    s.push(char::from_u32(cp).unwrap());
1055	                }
1056	                s
1057	            }
1058	            _ => {
1059	                return Err(format!(
1060	                    "unsupported attribute value string type (tag 0x{tag:02X})"
1061	                ))
1062	            }
1063	        };
1064	        Ok(s)
1065	    }
