1067	    /// RFC 4514 value escaping; everything above the ASCII control range
1068	    /// (including CJK text) passes through unchanged.
1069	    fn escape_value(value: &str) -> String {
1070	        let mut out = String::with_capacity(value.len());
1071	        let last = value.chars().count().saturating_sub(1);
1072	        for (i, c) in value.chars().enumerate() {
1073	            let at_edge = i == 0 || i == last;
1074	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
1075	                || (at_edge && (c == ' ' || c == '#'));
1076	            if needs_backslash {
1077	                out.push('\\');
1078	                out.push(c);
1079	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
1080	                let mut buf = [0u8; 4];
1081	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
1082	                write!(out, "\\{b:02X}").unwrap();
1083	            } else {
1084	                out.push(c);
1085	            }
1086	        }
1087	        out
1088	    }
1089	
1090	    fn format_time(tlv: Tlv) -> Result<String, String> {
1091	        let (y, mo, d, h, mi, se) = match tlv.tag {
1092	            TAG_UTC_TIME => {
1093	                let c = tlv.content;
1094	                if c.len() != 13 || c[12] != b'Z' {
1095	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
1096	                }
1097	                let digits = &c[..12];
