505	// ----- Certificate / DER construction --------------------------------------
506	
507	/// [3] EXPLICIT wrapping one Extensions SEQUENCE that holds the supplied,
508	/// already-encoded extension items.
509	fn extensions_field(extension_items: &[u8]) -> Vec<u8> {
510	    tlv(0xA3, &tlv(0x30, extension_items))
511	}
512	
513	/// Extension ::= SEQUENCE { extnID OID, critical BOOLEAN DEFAULT FALSE,
514	/// extnValue OCTET STRING }.
515	fn extension(arcs: &[u64], critical: Option<bool>, value: &[u8]) -> Vec<u8> {
516	    let mut content = oid(arcs);
517	    if let Some(flag) = critical {
518	        content.extend_from_slice(&tlv(0x01, &[if flag { 0xFF } else { 0x00 }]));
519	    }
520	    content.extend_from_slice(&tlv(0x04, value));
521	    tlv(0x30, &content)
522	}
523	
524	fn explicit_version(value: u8) -> Vec<u8> {
525	    tlv(0xA0, &tlv(0x02, &[value]))
526	}
527	
528	/// Assemble a complete certificate with fixed visible fields around the
529	/// optional explicit version (`None` = v1 with no version field) and an
530	/// arbitrary, already-encoded TBS tail (usually the extensions field).
531	fn build_cert(version: Option<u8>, tail: &[u8]) -> Vec<u8> {
532	    build_cert_times(version, tail, b"260115093000Z", b"270115093000Z")
533	}
534	
535	fn build_cert_times(
536	    version: Option<u8>,
537	    tail: &[u8],
538	    not_before: &[u8],
539	    not_after: &[u8],
540	) -> Vec<u8> {
541	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
542	    let validity = seq(&concat(&[
543	        &tlv(0x17, not_before),
544	        &tlv(0x17, not_after),
545	    ]));
546	    let subject = simple_cn_name("example.com");
547	    let issuer = simple_cn_name("Test CA");
548	    let spki = spki();
549	
550	    let mut tbs_content = Vec::new();
551	    if let Some(v) = version {
552	        tbs_content.extend_from_slice(&explicit_version(v));
553	    }
554	    tbs_content.extend_from_slice(&serial);
555	    tbs_content.extend_from_slice(&signature_algorithm());
556	    tbs_content.extend_from_slice(&issuer);
557	    tbs_content.extend_from_slice(&validity);
558	    tbs_content.extend_from_slice(&subject);
559	    tbs_content.extend_from_slice(&spki);
560	    tbs_content.extend_from_slice(tail);
561	    let tbs = seq(&tbs_content);
562	
563	    seq(&concat(&[
564	        &tbs,
565	        &signature_algorithm(),
566	        &tlv(0x03, &[0x00]),
567	    ]))
568	}
569	
570	fn signature_algorithm() -> Vec<u8> {
571	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
572	}
573	
574	fn spki() -> Vec<u8> {
575	    let alg = seq(&concat(&[
576	        &oid(&[1, 2, 840, 113549, 1, 1, 1]),
577	        &tlv(0x05, &[]),
578	    ]));
579	    seq(&concat(&[&alg, &tlv(0x03, &[0x00, 0x01, 0x00])]))
580	}
581	
582	fn simple_cn_name(cn: &str) -> Vec<u8> {
583	    let atv = seq(&concat(&[&oid(&[2, 5, 4, 3]), &tlv(0x0C, cn.as_bytes())]));
584	    let rdn = tlv(0x31, &atv);
585	    tlv(0x30, &rdn)
586	}
587	
588	/// TLV with caller-supplied length bytes; used to forge truncated encodings.
589	fn raw_tlv(tag: u8, len_bytes: &[u8], content: &[u8]) -> Vec<u8> {
590	    let mut out = vec![tag];
591	    out.extend_from_slice(len_bytes);
592	    out.extend_from_slice(content);
593	    out
594	}
595	
596	fn oid(arcs: &[u64]) -> Vec<u8> {
597	    assert!(arcs.len() >= 2);
598	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
599	    for &arc in &arcs[2..] {
600	        content.extend_from_slice(&oid_arc(arc));
601	    }
602	    tlv(0x06, &content)
603	}
604	
605	fn oid_arc(mut value: u64) -> Vec<u8> {
606	    let mut out = vec![(value % 128) as u8];
607	    value /= 128;
608	    while value > 0 {
609	        out.push(0x80 | (value % 128) as u8);
610	        value /= 128;
611	    }
612	    out.reverse();
613	    out
614	}
615	
616	fn seq(content: &[u8]) -> Vec<u8> {
617	    tlv(0x30, content)
618	}
619	
620	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
621	    let mut out = vec![tag];
622	    out.extend_from_slice(&der_len(content.len()));
623	    out.extend_from_slice(content);
624	    out
625	}
626	
627	fn der_len(n: usize) -> Vec<u8> {
628	    if n < 0x80 {
629	        vec![n as u8]
630	    } else {
631	        let mut body = Vec::new();
632	        let mut v = n;
633	        while v > 0 {
634	            body.push((v & 0xFF) as u8);
635	            v >>= 8;
636	        }
637	        body.reverse();
638	        let mut out = vec![0x80 | body.len() as u8];
639	        out.extend_from_slice(&body);
640	        out
641	    }
642	}
643	
644	fn concat(parts: &[&[u8]]) -> Vec<u8> {
645	    let mut out = Vec::new();
646	    for part in parts {
647	        out.extend_from_slice(part);
648	    }
649	    out
650	}
651

